import{_ as e,o,c as r,a2 as t}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":null}'),l={name:"guide/faq.md"};function d(i,a,n,c,s,h){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="连接相关" tabindex="-1">连接相关 <a class="header-anchor" href="#连接相关" aria-label="Permalink to &quot;连接相关&quot;">​</a></h2><h3 id="页面一直显示-未连接" tabindex="-1">页面一直显示&quot;未连接&quot;？ <a class="header-anchor" href="#页面一直显示-未连接" aria-label="Permalink to &quot;页面一直显示&quot;未连接&quot;？&quot;">​</a></h3><ol><li>确认本机打印服务已启动（系统托盘有打印机图标）；</li><li>确认服务端口正常监听：<code>netstat -ano | findstr 54321</code>；</li><li>确认 SDK 的 <code>url</code> 指向 <code>ws://127.0.0.1:54321</code>（默认即此地址）；</li><li>浏览器安全策略：本页必须通过 <code>http://</code> 或 <code>https://</code> 打开（部分浏览器限制 file:// 下的 WebSocket，请使用本地 HTTP 服务访问 demo）。</li></ol><h3 id="为什么服务只监听-127-0-0-1" tabindex="-1">为什么服务只监听 127.0.0.1？ <a class="header-anchor" href="#为什么服务只监听-127-0-0-1" aria-label="Permalink to &quot;为什么服务只监听 127.0.0.1？&quot;">​</a></h3><p>出于安全考虑，服务默认只绑定回环地址，<strong>不对外开放网卡端口</strong>。如需局域网访问，将 <code>MainApp</code> 中的 <code>WS_HOST</code> 改为 <code>0.0.0.0</code>，但<strong>必须自行增加鉴权</strong>（本项目未内置）。</p><h2 id="打印相关" tabindex="-1">打印相关 <a class="header-anchor" href="#打印相关" aria-label="Permalink to &quot;打印相关&quot;">​</a></h2><h3 id="打印内容空白或样式丢失" tabindex="-1">打印内容空白或样式丢失？ <a class="header-anchor" href="#打印内容空白或样式丢失" aria-label="Permalink to &quot;打印内容空白或样式丢失？&quot;">​</a></h3><ul><li>确认 <code>content.value</code> 是完整内容，<code>type</code> 与内容匹配（文本用 <code>text</code>，富样式用 <code>html</code>）；</li><li>HTML 请使用<strong>内联 style</strong>，外部 CSS 不会被加载；</li><li>图片使用 base64 或 http(s) 可访问地址。</li></ul><h3 id="打印没有反应-任务失败" tabindex="-1">打印没有反应 / 任务失败？ <a class="header-anchor" href="#打印没有反应-任务失败" aria-label="Permalink to &quot;打印没有反应 / 任务失败？&quot;">​</a></h3><ul><li>通过 <code>getTaskStatus(taskId)</code> 查询任务，<code>FAILED</code> 状态的 <code>errorMessage</code> 会说明原因；</li><li>确认选择了真实存在的打印机；</li><li>查看打印服务日志（SLF4J Simple 输出）。</li></ul><h3 id="想静默打印-不弹系统对话框" tabindex="-1">想静默打印，不弹系统对话框？ <a class="header-anchor" href="#想静默打印-不弹系统对话框" aria-label="Permalink to &quot;想静默打印，不弹系统对话框？&quot;">​</a></h3><p><code>doPrint()</code> 本身就是静默打印——内容渲染为 PDF 后直接输出到指定打印机，<strong>不弹系统打印对话框</strong>。</p><h2 id="安装与打包相关" tabindex="-1">安装与打包相关 <a class="header-anchor" href="#安装与打包相关" aria-label="Permalink to &quot;安装与打包相关&quot;">​</a></h2><h3 id="系统托盘图标不显示" tabindex="-1">系统托盘图标不显示？ <a class="header-anchor" href="#系统托盘图标不显示" aria-label="Permalink to &quot;系统托盘图标不显示？&quot;">​</a></h3><p>SWT 的 <code>display.getSystemTray()</code> 在 Windows / macOS 上支持；Linux 部分桌面环境需要扩展。</p><h3 id="打包-exe-后运行无反应-swt-报错" tabindex="-1">打包 exe 后运行无反应 / SWT 报错？ <a class="header-anchor" href="#打包-exe-后运行无反应-swt-报错" aria-label="Permalink to &quot;打包 exe 后运行无反应 / SWT 报错？&quot;">​</a></h3><ul><li>症状：运行 exe 无界面、进程一闪而过；<code>java -jar</code> 报 <code>Libraries for platform win32 cannot be loaded because of incompatible environment</code></li><li>原因：用 shade 的 fat jar 打包，SWT 本地库（dll）被破坏</li><li>解决：改用「瘦 jar + 原始依赖」通过 jpackage 打包，详见<a href="./installation">安装部署</a></li></ul><h3 id="为什么之前用-dorkbox-会报-bounds-is-null" tabindex="-1">为什么之前用 dorkbox 会报 <code>bounds is null</code>？ <a class="header-anchor" href="#为什么之前用-dorkbox-会报-bounds-is-null" aria-label="Permalink to &quot;为什么之前用 dorkbox 会报 `bounds is null`？&quot;">​</a></h3><p>dorkbox SystemTray 在 Windows 原生托盘上的已知 bug（issue #209）。本项目已改用 <strong>SWT 原生托盘</strong>，不再依赖 dorkbox。</p><h2 id="bartender-相关" tabindex="-1">BarTender 相关 <a class="header-anchor" href="#bartender-相关" aria-label="Permalink to &quot;BarTender 相关&quot;">​</a></h2><h3 id="bartender-available-为-false" tabindex="-1">BarTender <code>available</code> 为 false？ <a class="header-anchor" href="#bartender-available-为-false" aria-label="Permalink to &quot;BarTender `available` 为 false？&quot;">​</a></h3><p>确认本机已正确安装并启动 BarTender 软件；版本信息可通过 <code>getBartenderInstance().version</code> 查看。</p><h3 id="模板路径怎么写" tabindex="-1">模板路径怎么写？ <a class="header-anchor" href="#模板路径怎么写" aria-label="Permalink to &quot;模板路径怎么写？&quot;">​</a></h3><p>使用本机绝对路径，如 <code>D:\\labels\\mylabel.btw</code>，注意 JS 字符串中 <code>\\</code> 需写成 <code>\\\\</code>。</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><h3 id="如何开机自启" tabindex="-1">如何开机自启？ <a class="header-anchor" href="#如何开机自启" aria-label="Permalink to &quot;如何开机自启？&quot;">​</a></h3><ul><li><strong>Windows</strong>：快捷方式放入「启动」文件夹；或安装时勾选开机自启；</li><li><strong>macOS</strong>：登录项；</li><li><strong>Linux</strong>：systemd 或 <code>.desktop</code>。</li></ul><h3 id="跨平台支持吗" tabindex="-1">跨平台支持吗？ <a class="header-anchor" href="#跨平台支持吗" aria-label="Permalink to &quot;跨平台支持吗？&quot;">​</a></h3><p>默认面向 Windows x86_64。通过替换 <code>pom.xml</code> 中的 SWT artifact 可适配 macOS aarch64 与 Linux x86_64，详见<a href="./installation">安装部署</a>。</p><h3 id="有哪些授权方式" tabindex="-1">有哪些授权方式？ <a class="header-anchor" href="#有哪些授权方式" aria-label="Permalink to &quot;有哪些授权方式？&quot;">​</a></h3><p>内置机器码展示与授权码输入、取消授权、邮箱联系入口。授权相关代码经过 ProGuard 混淆加固。</p><blockquote><p>仍无法解决？请查看<a href="/changelog">更新日志</a>确认版本，或联系 I Teach You 团队。</p></blockquote>',33)])])}const q=e(l,[["render",d]]);export{b as __pageData,q as default};
